import{_ as a,o as t,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const c=JSON.parse('{"title":"Upgrading","description":"What happens when a new Piwi version starts, how to upgrade safely, why there is no downgrade, and what to do when an upgrade goes wrong.","frontmatter":{"title":"Upgrading","description":"What happens when a new Piwi version starts, how to upgrade safely, why there is no downgrade, and what to do when an upgrade goes wrong.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/upgrading.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/upgrading.html"}],["meta",{"property":"og:title","content":"Upgrading | Piwi Dashboard"}],["meta",{"property":"og:description","content":"What happens when a new Piwi version starts, how to upgrade safely, why there is no downgrade, and what to do when an upgrade goes wrong."}]]},"headers":[],"relativePath":"operate/upgrading.md","filePath":"operate/upgrading.md","lastUpdated":1790454954000}'),i={name:"operate/upgrading.md"};function n(o,e,h,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>Piwi is pre-1.0. Patch and minor releases can carry breaking changes, and the database schema moves with them. Upgrading is normally a one-line change — but it&#39;s a one-way door, so it&#39;s worth knowing what happens before you pull a new tag.</p><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><ol><li>Read the <a href="https://github.com/PiwiTests/platform/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> for the versions you&#39;re skipping, looking for <strong>⚠ BREAKING CHANGES</strong>.</li><li><strong>Back up</strong> the database and file storage (<a href="./backup-restore.html">how</a>).</li><li>Pull the new tag and restart.</li><li>Check the logs for <code>migrations completed successfully</code>, then confirm the version at <strong>Settings → About</strong>.</li></ol><h2 id="what-happens-when-a-new-version-starts" tabindex="-1">What happens when a new version starts <a class="header-anchor" href="#what-happens-when-a-new-version-starts" aria-label="Permalink to &quot;What happens when a new version starts&quot;">​</a></h2><p>On boot, before the server accepts a single request:</p><ol><li><strong>Database migrations run automatically</strong> — SQLite or PostgreSQL, whichever you&#39;re on. There is no separate migrate command and nothing to run by hand. Before migrating, Piwi compares the migrations the database has recorded with the ones this version ships (see <a href="#a-database-that-ran-another-build">A database that ran another build</a>).</li><li><strong>A project-assignments backfill</strong> runs (idempotent, safe on every start).</li><li><strong>Failure clusters are re-fingerprinted</strong> if the fingerprint algorithm changed in this release. This is non-destructive: existing clusters are updated in place, and clusters that now collide are merged rather than dropped, so your triage statuses and notes survive.</li></ol><p>Steps 2 and 3 log an error and continue if they fail — they never block startup. <strong>Step 1 does not.</strong> If a migration fails, the server refuses to start rather than serving against a half-migrated schema. That&#39;s deliberate: a loud failure you can restore from beats silent corruption.</p><h2 id="a-database-that-ran-another-build" tabindex="-1">A database that ran another build <a class="header-anchor" href="#a-database-that-ran-another-build" aria-label="Permalink to &quot;A database that ran another build&quot;">​</a></h2><p>Releases only ever add migrations, in date order. A database that also ran a build from outside the releases (a development branch, a preview image) can hold migrations this version does not ship, and be missing some it does. On startup Piwi logs <code>The migration history of this database does not match this build</code>, lists what differs, and repairs it in a single transaction:</p><ul><li>the migrations the database lacks are applied, including any dated before the latest one it ran;</li><li>tables, columns, indexes and constraints the other build already created are kept, completed with the columns this version declares, and indexes are rebuilt from this version&#39;s definition;</li><li>a unique index this version does not declare is dropped, since it would reject rows Piwi writes;</li><li>the result is checked against the schema this version expects, then the migrations the other build recorded are removed from the history.</li></ul><p>The log ends with <code>Migration history repaired</code> and the next start is a normal one. If the result would still differ from the expected schema — a column only the other build has, <code>NOT NULL</code> without a default, for instance — nothing is changed and the server stops with <code>Migration history repair failed</code> and the difference it found: restore a backup, or start from an empty database.</p><p>A database that is only <strong>ahead</strong> of this version, as after starting an older version on it, gets a single warning, <code>applied migration(s) are not in this build</code>, and nothing else: see below.</p><h2 id="downgrading-is-not-supported" tabindex="-1">Downgrading is not supported <a class="header-anchor" href="#downgrading-is-not-supported" aria-label="Permalink to &quot;Downgrading is not supported&quot;">​</a></h2><p>Migrations are <strong>forward-only</strong> — there are no down migrations. Once a new version has migrated your database, an older version will not run against it correctly, and starting one may make things worse.</p><p>So the rollback path is not &quot;pull the old tag&quot;, it&#39;s <strong>restore your backup</strong>:</p><ol><li>Stop the container.</li><li>Restore the database and <code>.data/storage/</code> from the backup you took before upgrading.</li><li>Start the previous version&#39;s tag.</li></ol><p>This is the entire reason step 2 of the short version isn&#39;t optional.</p><h2 id="pin-a-version" tabindex="-1">Pin a version <a class="header-anchor" href="#pin-a-version" aria-label="Permalink to &quot;Pin a version&quot;">​</a></h2><p>Running <code>latest</code> in production means an unattended <code>docker pull</code> can move you across a breaking change. Pin the exact version and bump it deliberately:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># docker-compose.yml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  piwi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">phenx/piwitests-server:0.26.1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # not :latest</span></span></code></pre></div><p>The available tag patterns — and the GHCR mirror — are in <a href="./deployment.html#available-tags">Deployment → Available tags</a>.</p><h2 id="verifying-the-upgrade-landed" tabindex="-1">Verifying the upgrade landed <a class="header-anchor" href="#verifying-the-upgrade-landed" aria-label="Permalink to &quot;Verifying the upgrade landed&quot;">​</a></h2><p>Three ways, in increasing order of automation:</p><ul><li><p><strong>Settings → About</strong> shows the running version, the build SHA, the Node version, and which database backend is active.</p></li><li><p><code>GET /api/version</code> returns the same thing as JSON, with no authentication required:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3000/api/version</span></span></code></pre></div></li><li><p><code>GET /api/health</code> is the readiness probe — it verifies database connectivity and returns 503 when the database isn&#39;t reachable, which is what you want a container orchestrator watching.</p></li></ul><p>In the startup logs, the lines worth grepping for are <code>Running &lt;dialect&gt; migrations from …</code> and <code>migrations completed successfully</code> — plus <code>Migration history repaired</code> after a <a href="#a-database-that-ran-another-build">repair</a>.</p><h2 id="upgrading-the-reporter" tabindex="-1">Upgrading the reporter <a class="header-anchor" href="#upgrading-the-reporter" aria-label="Permalink to &quot;Upgrading the reporter&quot;">​</a></h2><p>The reporter and the dashboard version independently, and you do <strong>not</strong> have to upgrade them in lockstep:</p><ul><li>A <strong>newer reporter against an older server</strong> degrades gracefully — if the server doesn&#39;t understand streaming, the reporter falls back to batch submission on its own.</li><li>An <strong>older reporter against a newer server</strong> keeps working; wire fields are added, not repurposed.</li></ul><p>That said, features land in pairs. Locator healing needs both a reporter that captures snapshots and a server that ranks them, so if a new capability doesn&#39;t appear, matching the two versions is the first thing to try.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter@latest</span></span></code></pre></div><h2 id="upgrading-the-desktop-app" tabindex="-1">Upgrading the desktop app <a class="header-anchor" href="#upgrading-the-desktop-app" aria-label="Permalink to &quot;Upgrading the desktop app&quot;">​</a></h2><p>The <a href="/features/desktop.html">desktop build</a> bundles its own server, so installing a newer build upgrades both. Its database lives outside the app bundle and is migrated on first launch, exactly as the server does — which means the same forward-only rule applies. Back up its data directory before a major jump. On Windows an in-app update closes the app as soon as the download finishes and hands over to the installer, which reopens it when done.</p><h2 id="if-an-upgrade-goes-wrong" tabindex="-1">If an upgrade goes wrong <a class="header-anchor" href="#if-an-upgrade-goes-wrong" aria-label="Permalink to &quot;If an upgrade goes wrong&quot;">​</a></h2><p><strong>The container won&#39;t start after upgrading.</strong> Check the logs for <code>Migration error</code>. The schema is mid-flight or incompatible; restore your backup and open an <a href="https://github.com/PiwiTests/platform/issues" target="_blank" rel="noreferrer">issue</a> with the error. If the error starts with <code>Migration history repair failed</code>, the database ran another build and could not be brought in line automatically (<a href="#a-database-that-ran-another-build">details</a>); it was left as it was.</p><p><strong>The dashboard loads but data looks wrong.</strong> Don&#39;t downgrade — restore the backup instead, then report what you saw. Downgrading on a migrated database compounds the problem.</p><p><strong>The Windows desktop installer says &quot;Error opening file for writing&quot;.</strong> Up to version 0.37, an in-app update could leave the app&#39;s bundled server running — a <code>node.exe</code> in the install folder, <code>%LOCALAPPDATA%\\Piwi Dashboard</code> for the <code>.exe</code> — and the installer could not replace the files it holds. Installers from later versions stop it first. If you hit it, don&#39;t choose <strong>Ignore</strong>, which leaves an old file behind: in Task Manager&#39;s <strong>Details</strong> tab, end the <code>node.exe</code> whose <strong>Open file location</strong> is that folder, then choose <strong>Retry</strong>.</p><p><strong>Failure clusters look reorganized.</strong> Expected after a fingerprint-algorithm change: clusters that now share a root cause have merged. Triage state is carried across the merge.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./backup-restore.html">Backup &amp; restore</a> — what to back up and how</li><li><a href="./deployment.html#available-tags">Deployment → Available tags</a> — what to pin</li><li><a href="https://github.com/PiwiTests/platform/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Changelog</a> — breaking changes per release</li></ul>`,40)])])}const u=a(i,[["render",n]]);export{c as __pageData,u as default};
